use super::helpers::compile_ok;

#[test] fn declaratives_use_after_error_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nPROCEDURE DIVISION.\nDECLARATIVES.\nERR-SEC SECTION.\n    USE AFTER STANDARD ERROR PROCEDURE ON WS-FILE.\nEND DECLARATIVES.\nMAIN-SEC SECTION.\n    DISPLAY \"RUN\".\n    STOP RUN."); }
#[test] fn declaratives_use_after_exception_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nPROCEDURE DIVISION.\nDECLARATIVES.\nEX-SEC SECTION.\n    USE FOR DEBUGGING ON ALL PROCEDURES.\nEND DECLARATIVES.\nMAIN-SEC SECTION.\n    DISPLAY \"RUN\".\n    STOP RUN."); }
#[test] fn declaratives_and_main_flow_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nPROCEDURE DIVISION.\nDECLARATIVES.\nD1 SECTION.\n    USE AFTER STANDARD ERROR PROCEDURE ON WS-FILE.\nEND DECLARATIVES.\nM1 SECTION.\n    DISPLAY \"MAIN\".\n    STOP RUN."); }
#[test] fn declaratives_with_call_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nPROCEDURE DIVISION.\nDECLARATIVES.\nD2 SECTION.\n    USE AFTER STANDARD ERROR PROCEDURE ON WS-FILE.\nEND DECLARATIVES.\nM2 SECTION.\n    CALL \"WORK\".\n    STOP RUN."); }
#[test] fn declaratives_empty_then_main_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nPROCEDURE DIVISION.\nDECLARATIVES.\nEND DECLARATIVES.\nMAIN SECTION.\n    DISPLAY \"OK\".\n    STOP RUN."); }
#[test] fn declaratives_section_labels_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nPROCEDURE DIVISION.\nDECLARATIVES.\nD-A SECTION.\n    USE AFTER STANDARD ERROR PROCEDURE ON WS-FILE.\nD-B SECTION.\n    USE AFTER STANDARD ERROR PROCEDURE ON WS-FILE.\nEND DECLARATIVES.\nMAIN SECTION.\n    DISPLAY \"OK\".\n    STOP RUN."); }
